from itertools import combinations, product
import z3,time

def check(t,k,aa,extra=0):
    cores=[]; n=0
    for a in aa:
        cores.append(set(range(n,n+k-a)));n+=k-a
    n+=extra
    edges=[]
    for i,(a,C) in enumerate(zip(aa,cores)):
        for P in combinations(set(range(n))-C,a): edges.append((i,frozenset(C|set(P))))
    s=z3.Solver();s.set(timeout=60000)
    xs=[z3.Bool(f'x{i}') for i in range(len(edges))]
    for i in range(t): s.add(z3.Or([x for x,(j,E) in zip(xs,edges) if i==j]))
    for p,(_,E) in enumerate(edges):
        for q in range(p):
            if E.isdisjoint(edges[q][1]): s.add(z3.Or(z3.Not(xs[p]),z3.Not(xs[q])))
    for C in combinations(range(n),t-1):
        C=set(C);s.add(z3.Or([x for x,(_,E) in zip(xs,edges) if C.isdisjoint(E)]))
    r=s.check();print(aa,extra,'edges',len(edges),r,flush=True)
    if r==z3.sat:
        m=s.model();print(cores,[e for x,e in zip(xs,edges) if m.eval(x)],flush=True)
for aa in [(0,1,1,3),(0,1,2,2),(1,1,1,2)]:check(4,4,aa)

