from itertools import combinations
import z3,time

def search(mode):
 t=6;k=6;a=2;extra=2
 cores=[set(range(4*i,4*i+4)) for i in range(t)];n=24+extra
 edges=[]
 for i,C in enumerate(cores):
  for P in combinations(set(range(n))-C,a):edges.append((i,frozenset(C|set(P))))
 xs=[z3.Bool('e%d'%p) for p in range(len(edges))]
 s=z3.Solver();s.set(timeout=600000)
 for i in range(t):s.add(z3.Or([x for x,(j,E) in zip(xs,edges) if i==j]))
 for p,(_,E) in enumerate(edges):
  for q in range(p):
   if E.isdisjoint(edges[q][1]):s.add(z3.Or(z3.Not(xs[p]),z3.Not(xs[q])))
 for C in combinations(range(n),t-1):
  C=set(C);s.add(z3.Or([x for x,(_,E) in zip(xs,edges) if C.isdisjoint(E)]))
 P={4,5} if mode=='B' else {4,24}
 target=cores[0]|P
 s.add(xs[next(p for p,(i,E) in enumerate(edges) if i==0 and E==target)])
 r=s.check();print(mode,r,flush=True)
 if r==z3.sat:
  model=s.model();chosen=[(i,sorted(E-set(cores[i]))) for x,(i,E) in zip(xs,edges) if model.eval(x)]
  print(chosen,flush=True)
search('B')
search('C')

